 	getById: seasonProcedure
 		.input(
 			z.object({
 				seasonSlug: z.string(),
 				matchId: z.string(),
 			})
 		)
 		.query(async ({ ctx, input }) => {
 			return matchRepository.getMatchWithPlayers({
