4b. Replace `finalizeMatchCreation` entirely. Its current signature has `createdMatch: { id: string };` and `seasonPlayerIds: string[];`, and its body broadcasts `match:insert` with `data: { match: createdMatch, standings }`, then checks streaks, then sends `ACHIEVEMENT_QUEUE.send({ seasonPlayerIds, leagueSlug, seasonSlug })`, and returns `createdMatch`. Replace it with:

```ts
async function finalizeMatchCreation({
	ctx,
	seasonSlug,
	seasonId,
	createdMatch,
	seasonPlayerIds,
	scoreType,
}: {
	ctx: {
		db: Parameters<typeof seasonPlayerRepository.getStanding>[0]["db"];
		env: Pick<Env, "SEASON_SSE" | "ACHIEVEMENT_QUEUE">;
		waitUntil: (promise: Promise<unknown>) => void;
		organization: { slug: string };
		authentication: { user: { id: string; name: string } };
	};
	seasonSlug: string;
	seasonId: string;
	createdMatch: {
		id: string;
		seasonId: string;
		homeScore: number;
		awayScore: number;
		createdAt: Date;
	};
	seasonPlayerIds: string[];
	scoreType: SeasonScoreType;
}) {
	const standings = await seasonPlayerRepository.getStanding({
		db: ctx.db,
		seasonId,
	});

	const data = await buildMatchInsertData(ctx.db, {
		match: createdMatch,
		scoreType,
		standings,
	});

	ctx.waitUntil(
		broadcastSeasonEvent(ctx.env, ctx.organization.slug, seasonSlug, {
			type: "match:insert",
			data,
			user: {
				id: ctx.authentication.user.id,
				name: ctx.authentication.user.name,
			},
		})
	);

	const [streakPlayers, streakTeams] = await Promise.all([
		matchRepository.checkStreakThresholds({
			db: ctx.db,
			seasonPlayerIds,
		}),
		matchRepository.checkTeamStreakThresholds({
			db: ctx.db,
			matchId: createdMatch.id,
		}),
	]);

	broadcastStreakEvents(
		ctx.waitUntil.bind(ctx),
		ctx.env,
		ctx.organization.slug,
		seasonSlug,
		streakPlayers,
		streakTeams,
		{
			id: ctx.authentication.user.id,
			name: ctx.authentication.user.name,
		}
	);

	await ctx.env.ACHIEVEMENT_QUEUE.send({
		seasonPlayerIds,
		leagueSlug: ctx.organization.slug,
		seasonSlug,
	} satisfies AchievementQueueMessage);

	return createdMatch;
}
```

